#include "project.h"
#include <QJsonArray>
#include <QRegularExpression>
#include <cmath>
namespace cf {
namespace {
QJsonArray noteJson(const QVector<SoundNote> &notes){QJsonArray out;for(auto n:notes)out.append(QJsonObject{{"note",n.note},{"ticks",n.ticks},{"volume",n.volume},{"noise",n.noise}});return out;}
bool integer(QJsonValue v,int lo,int hi){return v.isDouble()&&v.toDouble()==v.toInt(lo-1)&&v.toInt()>=lo&&v.toInt()<=hi;}
bool notesFrom(QJsonValue value,QVector<SoundNote> &out){if(!value.isArray()||value.toArray().isEmpty()||value.toArray().size()>64)return false;out.clear();for(auto entry:value.toArray()){auto n=entry.toObject();if(!integer(n["note"],0,107)||(n["note"].toInt()!=0&&n["note"].toInt()<36)||!integer(n["ticks"],1,255))return false;for(auto key:{"volume","noise"})if(n.contains(key)&&!integer(n[key],-1,key==QString("volume")?15:255))return false;out<<SoundNote{n["note"].toInt(),n["ticks"].toInt(),n["volume"].toInt(-1),n["noise"].toInt(-1)};}return true;}
int duration(const QVector<SoundNote> &notes){int n=0;for(auto v:notes)n+=v.ticks;return n;}
}
void expandSoundChannels(SoundClip &clip){if(!clip.channels.isEmpty())return;SoundTrack lead;lead.duty=clip.duty;lead.volume=clip.volume;lead.notes=clip.notes;clip.channels<<lead;int ticks=duration(clip.notes);for(int i=1;i<4;++i){SoundTrack track;track.enabled=false;track.notes.clear();int remaining=ticks;while(remaining){int n=qMin(remaining,255);track.notes<<SoundNote{0,n};remaining-=n;}clip.channels<<track;}}
QJsonObject soundJson(const SoundClip &s){QJsonObject out{{"id",s.id},{"name",s.name},{"bpm",s.bpm},{"duty",s.duty},{"volume",s.volume},{"notes",noteJson(s.notes)},{"effect",s.effect},{"masterLeft",s.masterLeft},{"masterRight",s.masterRight}};
 if(!s.channels.isEmpty()){QJsonArray tracks;for(auto &t:s.channels){QJsonArray wave;for(int v:t.wave)wave.append(v);tracks.append(QJsonObject{{"enabled",t.enabled},{"dac",t.dac},{"duty",t.duty},{"volume",t.volume},{"pan",t.pan},{"envelopePace",t.envelopePace},{"envelopeUp",t.envelopeUp},{"sweepPace",t.sweepPace},{"sweepShift",t.sweepShift},{"sweepDown",t.sweepDown},{"length",t.length},{"waveLevel",t.waveLevel},{"wave",wave},{"noiseShift",t.noiseShift},{"noiseDivider",t.noiseDivider},{"noiseNarrow",t.noiseNarrow},{"drumKit",t.drumKit},{"notes",noteJson(t.notes)}});}out["channels"]=tracks;}return out;
}
bool readSound(const QJsonObject &o,SoundClip &s,QString &error){auto fail=[&]{error="Invalid sound pattern or channel settings.";return false;};if(!o["id"].isString()||!o["name"].isString()||!integer(o["bpm"],30,300)||!integer(o["duty"],0,3)||!integer(o["volume"],0,15)||!notesFrom(o["notes"],s.notes))return fail();if(o.contains("effect")&&!o["effect"].isBool())return fail();s.effect=o["effect"].toBool();s.id=o["id"].toString();s.name=o["name"].toString();s.bpm=o["bpm"].toInt();s.duty=o["duty"].toInt();s.volume=o["volume"].toInt();for(auto key:{"masterLeft","masterRight"})if(o.contains(key)&&!integer(o[key],0,7))return fail();s.masterLeft=o["masterLeft"].toInt(7);s.masterRight=o["masterRight"].toInt(7);s.channels.clear();
 if(o.contains("channels")){if(!o["channels"].isArray()||o["channels"].toArray().size()!=4)return fail();for(auto value:o["channels"].toArray()){if(!value.isObject())return fail();auto v=value.toObject();SoundTrack t;for(auto key:{"enabled","dac","envelopeUp","sweepDown","noiseNarrow","drumKit"})if(!v[key].isBool())return fail();t.enabled=v["enabled"].toBool();t.dac=v["dac"].toBool();t.envelopeUp=v["envelopeUp"].toBool();t.sweepDown=v["sweepDown"].toBool();t.noiseNarrow=v["noiseNarrow"].toBool();t.drumKit=v["drumKit"].toBool();
 struct Field{const char *key;int *target,lo,hi;};for(auto f:{Field{"duty",&t.duty,0,3},{"volume",&t.volume,0,15},{"pan",&t.pan,0,3},{"envelopePace",&t.envelopePace,0,7},{"sweepPace",&t.sweepPace,0,7},{"sweepShift",&t.sweepShift,0,7},{"length",&t.length,0,256},{"waveLevel",&t.waveLevel,0,3},{"noiseShift",&t.noiseShift,0,15},{"noiseDivider",&t.noiseDivider,0,7}}){if(!integer(v[f.key],f.lo,f.hi))return fail();*f.target=v[f.key].toInt();}if(!v["wave"].isArray()||v["wave"].toArray().size()!=32||!notesFrom(v["notes"],t.notes))return fail();t.wave.clear();for(auto n:v["wave"].toArray()){if(!integer(n,0,15))return fail();t.wave<<n.toInt();}s.channels<<t;}}
 if(!validateSound(s).isEmpty())return fail();return true;
}
QStringList validateSound(const SoundClip &s){QStringList errors;auto bad=[&](QString text){errors<<s.id+": "+text;};if(QStringList{"blip","hit","chime","pulse","alarm"}.contains(s.id))bad("built-in sound names are reserved.");if(s.name.trimmed().isEmpty()||s.bpm<30||s.bpm>300||s.duty<0||s.duty>3||s.volume<0||s.volume>15||s.masterLeft<0||s.masterLeft>7||s.masterRight<0||s.masterRight>7)bad("invalid sound settings.");auto checkNotes=[&](const QVector<SoundNote> &notes){if(notes.isEmpty()||notes.size()>64)bad("use 1–64 notes/rests per channel.");for(auto n:notes)if((n.note!=0&&(n.note<36||n.note>107))||n.ticks<1||n.ticks>255||n.volume<-1||n.volume>15||n.noise<-1||n.noise>255)bad("invalid pitch, duration, velocity or noise override.");};checkNotes(s.notes);
 if(!s.channels.isEmpty()&&s.channels.size()!=4)bad("a song needs exactly four channel lanes.");for(int i=0;i<s.channels.size();++i){auto &t=s.channels[i];checkNotes(t.notes);if(t.duty<0||t.duty>3||t.volume<0||t.volume>15||t.pan<0||t.pan>3||t.envelopePace<0||t.envelopePace>7||t.sweepPace<0||t.sweepPace>7||t.sweepShift<0||t.sweepShift>7||t.length<0||t.length>(i==2?256:64)||t.waveLevel<0||t.waveLevel>3||t.noiseShift<0||t.noiseShift>15||t.noiseDivider<0||t.noiseDivider>7||t.wave.size()!=32)bad("invalid channel instrument settings.");for(int v:t.wave)if(v<0||v>15)bad("wave samples must be 0–15.");}return errors;
}
SoundClip foundryDemoSong(){SoundClip song;song.id="foundry_four";song.name="Foundry After Hours";song.bpm=150;expandSoundChannels(song);for(auto &t:song.channels){t.enabled=true;t.notes.clear();}auto &lead=song.channels[0];lead.duty=2;lead.volume=10;lead.envelopePace=3;lead.pan=1;auto &harmony=song.channels[1];harmony.duty=1;harmony.volume=6;harmony.envelopePace=4;harmony.pan=2;auto &bass=song.channels[2];bass.waveLevel=1;auto &drums=song.channels[3];drums.volume=9;drums.envelopePace=1;drums.drumKit=true;
 const int roots[]={48,44,41,43};const int melody[4][8]={{72,76,79,83,81,79,76,74},{72,75,79,82,79,75,72,70},{69,72,77,81,79,77,72,69},{71,74,79,83,81,79,74,71}};
 for(int bar=0;bar<8;++bar){int chord=bar%4;for(int step=0;step<8;++step){lead.notes<<SoundNote{melody[chord][step]+(bar>=4&&step==7?12:0),12,step%2?8:11};harmony.notes<<SoundNote{roots[chord]+12+(step%4==0?0:step%4==1?7:step%4==2?12:7),12};if(step%2==0)bass.notes<<SoundNote{roots[chord]+(step==6?7:0),24};int hit=step==0||step==4?36:step==2||step==6?38:42;drums.notes<<SoundNote{hit,12,hit==42?5:11};}}
 song.notes=lead.notes;song.duty=lead.duty;song.volume=lead.volume;return song;
}
}
